from collections import defaultdict

def two_sum(nums: list[int], target: int) -> tuple[int, int] | None:
    seen = {}                               # value -> index
    for i, x in enumerate(nums):
        if target - x in seen:              # check BEFORE storing: x can't pair with itself
            return seen[target - x], i
        seen[x] = i
    return None

def subarray_sum_k(nums: list[int], k: int) -> int:
    counts = {0: 1}                         # empty prefix: subarrays that start at index 0
    prefix = answer = 0
    for x in nums:
        prefix += x
        answer += counts.get(prefix - k, 0) # earlier prefixes p with prefix - p == k
        counts[prefix] = counts.get(prefix, 0) + 1
    return answer

def group_anagrams(words: list[str]) -> list[list[str]]:
    groups = defaultdict(list)
    for w in words:
        groups["".join(sorted(w))].append(w)  # canonical key
    return list(groups.values())
